"""Tests for the CHANGELOG.md version links generated by develop/copy_changelog.py."""

from develop.copy_changelog import REPO_URL, SOURCE, version_links, with_version_links

CHANGELOG = """\
# Changelog

## [0.4.0] - Unreleased

- Upcoming change

## [0.3.10] - 2026-10-18

- Patch release

## [0.3.0] - 2026-06-12

- Feature release

[0.3.0]: https://example.com/stale
"""


def test_version_links_oldest_first():
    assert version_links(CHANGELOG) == [
        f"[0.3.0]: {REPO_URL}/releases/tag/v0.3.0",
        f"[0.3.10]: {REPO_URL}/compare/v0.3.0...v0.3.10",
        f"[0.4.0]: {REPO_URL}/compare/v0.3.10...HEAD",
    ]


def test_with_version_links_replaces_existing_links():
    body = CHANGELOG.removesuffix("[0.3.0]: https://example.com/stale\n")
    assert with_version_links(CHANGELOG) == (
        body + f"[0.3.0]: {REPO_URL}/releases/tag/v0.3.0\n"
        f"[0.3.10]: {REPO_URL}/compare/v0.3.0...v0.3.10\n"
        f"[0.4.0]: {REPO_URL}/compare/v0.3.10...HEAD\n"
    )


def test_with_version_links_is_idempotent():
    once = with_version_links(CHANGELOG)
    assert with_version_links(once) == once


def test_changelog_links_are_current():
    # The copy-changelog prek hook keeps the links in sync; this catches commits that skipped it.
    text = SOURCE.read_text(encoding="utf-8")
    assert with_version_links(text) == text
